// 1. Extract existing files from the previous node
const files = items[0].json.files;

// 2. Filter to briefing files (date-prefixed .md files) and sort newest first
const briefingPattern = /^\d{4}-\d{2}-\d{2}.*\.md$/;
const existingBriefings = files
  .filter(f => briefingPattern.test(f))
  .sort((a, b) => b.localeCompare(a));

// 3. The previous briefing is simply the most recent existing one.
// Since filenames now include a timestamp (yyyy-MM-dd HH:mm), no run ever
// overwrites another, so we never need to skip the current run's file here —
// it hasn't been written yet when this node executes.
const previousBriefing = existingBriefings[0] || null;

return [{
  json: {
    all_briefings: existingBriefings,
    previous_briefing: previousBriefing
  }
}];

// ── 1. Extract raw LLM response ────────────────────────────────────────────────────────────────────
const responseText = $json.choices?.[0]?.message?.content || '';

// ── 2. Strip <think> blocks (Qwen3) ────────────────────────────────────────────────────────────
let briefingMarkdown = responseText.replace(/<think>[\s\S]*?<\/think>/g, '').trim();

// ── 3. Strip any footer line the LLM may have invented ─────────────────────────────────────────
briefingMarkdown = briefingMarkdown.replace(/\n[_*]{1,2}Generated by[^\n]*[_*]{1,2}\s*$/m, '').trimEnd();

// ── 4. SAFETY NET — strip appended source material ───────────────────────────────────────────
briefingMarkdown = briefingMarkdown.replace(/\n###\s*PROJECT INDEX[\s\S]*/i, '').trimEnd();
const housekeepingPos = briefingMarkdown.lastIndexOf('## 🔵 Housekeeping');
if (housekeepingPos !== -1) {
  const afterHousekeeping = briefingMarkdown.slice(housekeepingPos);
  const jsonLeakMatch = afterHousekeeping.match(/\n\n(\[|\{)/);
  if (jsonLeakMatch) {
    const leakOffset = housekeepingPos + jsonLeakMatch.index;
    briefingMarkdown = briefingMarkdown.slice(0, leakOffset).trimEnd();
  }
}

// ── 5. Strip callouts containing NO_NEW_SIGNALS sentinel ───────────────────────────────────
// The LLM emits NO_NEW_SIGNALS as the status bullet when nothing has changed.
// We strip the entire [!info] callout block deterministically here rather than
// asking the LLM to delete multi-line markdown (which risks formatting damage).
briefingMarkdown = briefingMarkdown.replace(
  />\s*\[!info\].*?\n(?:>.*\n)*?>[^\n]*NO_NEW_SIGNALS[^\n]*\n(?:>.*\n)*/g,
  ''
);

// ── 5b. Strip empty New tasks blocks from callouts ──────────────────────────────────────────
briefingMarkdown = briefingMarkdown.replace(
  /\n?>\s*\n>\s*\*\*New tasks\*\*\s*\n>\s*\*\(none\)\*\s*/gm,
  '\n\n'
);

// ── 6. Strip callout + Recent Activity for no-signal projects ──────────────────────────────
function stripNoSignalBlocks(markdown) {
  const segments = markdown.split(/((?:^|\n)### )/m);
  const result = [];
  result.push(segments[0]);
  for (let i = 1; i < segments.length; i += 2) {
    const prefix = segments[i];
    let body = segments[i + 1] || '';
    const hasNoSignals = /\|\s*No new signals[^|]*\|\s*[—-]\s*\|/i.test(body);
    if (hasNoSignals) {
      body = body.replace(/>\s*\[!info\][^\n]*\n(?:>.*\n)*/, '');
      body = body.replace(/\*\*Recent Activity:\*\*\n\n\|[^\n]+\|\n\|[-| ]+\|\n\|[^\n]*No new signals[^\n]*\|\n?/, '');
      body = body.replace(/\n{3,}/g, '\n\n');
    }
    result.push(prefix, body);
  }
  return result.join('');
}
briefingMarkdown = stripNoSignalBlocks(briefingMarkdown);

// ── 7. Performance metadata ───────────────────────────────────────────────────────────────────────
const configNode   = $('Config').first()?.json || {};
const rawStartTime = (configNode.starttime || '').replace(/^"|"$/g, '');
const modelUsed    = configNode.manualModelName || $json.model || 'unknown';

const startTime = rawStartTime ? new Date(rawStartTime).getTime() : null;
const endTime   = Date.now();

let generationTimeSec = 0;
if (startTime && !isNaN(startTime)) {
  generationTimeSec = parseFloat(((endTime - startTime) / 1000).toFixed(2));
}

const completionTokens = $json.usage?.completion_tokens || 0;
const totalTokens      = $json.usage?.total_tokens      || 0;
const tokensPerSecond  = generationTimeSec > 0
  ? parseFloat((completionTokens / generationTimeSec).toFixed(2))
  : 0;

const mins              = Math.floor(generationTimeSec / 60);
const secs              = (generationTimeSec % 60).toFixed(1);
const durationFormatted = mins > 0 ? `${mins}m ${secs}s` : `${secs}s`;

// ── 8. Time strings (NZT — for subtitle display only) ──────────────────────────────────────
const now     = new Date();
const timeStr = now.toLocaleTimeString('en-NZ', {
  hour: 'numeric', minute: '2-digit', hour12: true, timeZone: 'Pacific/Auckland'
});

// ── 9. generated_at: UTC ISO — used by Master on next run for feedsSince arithmetic ─────────────
const generatedAt = now.toISOString(); // e.g. "2026-04-14T19:32:00.000Z"

// ── 10. Previous briefing link ─────────────────────────────────────────────────────────────────────────
const buildPromptNode  = $('Code - Build Prompt').first()?.json || {};
const prevBriefingName = buildPromptNode.prevBriefingName || '';
const prevDateLink     = prevBriefingName.replace(/\.md$/i, '');

// ── 11. Subtitle line (under H1) ───────────────────────────────────────────────────────────────────────
const subtitleLine = prevDateLink
  ? `*← [[${prevDateLink}|Previous Briefing]]  ·  Generated ${timeStr}*`
  : `*Generated ${timeStr}*`;

// ── 12. Inject subtitle after H1 ──────────────────────────────────────────────────────────────────────
let withSubtitle = briefingMarkdown.replace(
  /^(# .+)\n/m,
  `$1\n${subtitleLine}\n\n`
);

// ── 13. YAML frontmatter — generated_at is UTC ISO for feedsSince lookup ───────────────────────
const frontmatter = `---\nmodel: "${modelUsed}"\nduration: "${durationFormatted}"\ntokens_per_sec: ${tokensPerSecond}\ntokens_completion: ${completionTokens}\ntokens_total: ${totalTokens}\ngenerated_at: "${generatedAt}"\n---`;

// ── 14. Assemble final document (no footer) ──────────────────────────────────────────────────────
const content = `${frontmatter}\n\n${withSubtitle}`;

return [{ json: { content, generatedAt, metadata: { model: modelUsed, duration: durationFormatted, generationTimeSeconds: generationTimeSec, tokensPerSecond, completionTokens, totalTokens } } }];

// ── Helpers ────────────────────────────────────────────────────────────────────
function parseFencedJSON(raw) {
  const stripped = raw.replace(/^---[\s\S]*?---\n?/, '').trim();
  const fence = '\u0060\u0060\u0060';
  const fenceRegex = new RegExp(fence + 'json\\s*([\\s\\S]*?)\\s*' + fence);
  const match = stripped.match(fenceRegex);
  if (match) return JSON.parse(match[1]);
  return JSON.parse(stripped);
}

function getContent(node) {
  const j = node.first().json;
  return j.content || j.data || '';
}

// Convert any ISO timestamp string to NZT 24-hour HH:MM
function toNZT(isoString) {
  if (!isoString) return '';
  try {
    return new Date(isoString).toLocaleTimeString('en-NZ', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
      timeZone: 'Pacific/Auckland'
    });
  } catch (e) {
    return '';
  }
}

// Walk a parsed feed array and stamp a time_nzt field onto every message
function stampNZT(feedArray) {
  if (!Array.isArray(feedArray)) return feedArray;
  return feedArray.map(msg => ({
    ...msg,
    time_nzt: toNZT(msg.timestamp)
  }));
}

// Compute days from today to a YYYY-MM-DD date string. Returns null if no date.
function daysUntil(dateStr) {
  if (!dateStr) return null;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const target = new Date(dateStr + 'T00:00:00');
  return Math.round((target - today) / (1000 * 60 * 60 * 24));
}

// ── 1. Collect inputs ──────────────────────────────────────────────────────────────────
const skeletonRaw      = getContent($('Fetch Skeleton'));
const projectIndexRaw  = getContent($('Fetch projects_index'));
const feedsRaw         = getContent($('Fetch Feeds'));
const prevBriefingRaw  = getContent($('Find Previous Briefing'));
const prevBriefingName = $('Identify Briefing Files').first().json.previous_briefing || '';

// ── 2. Parse structured data & stamp NZT times ─────────────────────────────────────────
const projectIndex     = parseFencedJSON(projectIndexRaw);
const categorizedFeeds = stampNZT(parseFencedJSON(feedsRaw));

// ── 3. Annotate each project with milestone proximity ──────────────────────────────────
const annotatedIndex = projectIndex.map(p => {
  const out = { ...p };
  // Strip current_status from the JSON — it's already in the skeleton body as **Current Status:**.
  // Sending it twice anchors the model to echo it into __proposed_current_status_bullets__.
  // Rollback: remove this line. No other nodes affected. (added 2026-06-29)
  delete out.current_status;
  for (const field of ['milestone_offline', 'milestone_online', 'milestone_delivery']) {
    if (p[field]) {
      out[field + '_days'] = daysUntil(p[field]);
    }
  }
  return out;
});

// ── 4. Get model from Config ─────────────────────────────────────────────────────────────────
const model = $('Config').first().json.manualModelName;

// ── 5. Build prompt ──────────────────────────────────────────────────────────────────
const systemPrompt = `You are an executive synthesis engine generating a personal daily briefing.

## THINKING MODE DISABLED
Do not use <think> tags.
Do not produce hidden or visible reasoning.
Output only final answers.

You will be given a skeleton briefing document containing placeholders in the format __PLACEHOLDER__. Replace every placeholder with the appropriate content as described below. Do not modify anything else — especially Tasks plugin code blocks (lines beginning with a backtick fence and containing task query syntax).

## YOUR INPUTS

### SKELETON BRIEFING
${skeletonRaw}

### PROJECT INDEX
Each project entry includes:
- open_tasks: tasks already captured and actively tracked — do NOT reproduce these as new tasks under any circumstances
- completed_tasks: tasks already finished — do NOT propose these again
- milestone_offline: date (YYYY-MM-DD) when the first offline/cut is due to the client. null if not set.
- milestone_online: date (YYYY-MM-DD) when grade & online are due to the client. null if not set.
- milestone_delivery: date (YYYY-MM-DD) when final masters are due. null if not set.
- milestone_offline_days / milestone_online_days / milestone_delivery_days: integer — days from today until that milestone (negative = overdue, 0 = today). Only present when the corresponding date is set.

Use milestone proximity to inform urgency. If milestone_offline_days <= 7 and not null, treat that project as high-priority in __proposed_actions__ and flag the upcoming deadline explicitly (e.g. "First offline due in 3 days"). Overdue milestones (negative days) should be flagged as critical.
${JSON.stringify(annotatedIndex, null, 2)}

### CATEGORISED FEEDS (today's signals)
Each message has a "time_nzt" field containing the pre-converted local time in 24-hour NZT (e.g. "14:23"). Use this field exactly as-is whenever you display a time. Do not perform any timezone conversion yourself.
${JSON.stringify(categorizedFeeds, null, 2)}

### PREVIOUS BRIEFING
${prevBriefingRaw}

## PLACEHOLDER DEFINITIONS

__signal_check__
One punchy sentence summarising the overall tone of today's signals. E.g. "Quiet day — one client reply pending, no blockers."

__proposed_actions__
3–5 bullet points. The highest-leverage actions Tim should take today based on feeds, open tasks, and project status. Be specific and actionable. If any project has a milestone within 7 days, lead with or prominently include that deadline.

__recent_updates__
For each relevant signal, write a table row: summary text in the Summary column, and the message's time_nzt value in the Time column. Use the time_nzt field verbatim — do not convert or reformat it. If no signals exist for this project today, write a single row: "No new signals today; status unchanged since last briefing. | —"

__resolution_summary__
Compare yesterday's open tasks (from the Previous Briefing) against today's signals. If any items appear closed or resolved, list them as bullet points with a ✓ prefix. If nothing is resolved, write "Nothing resolved since last briefing."

__starred_items__
Collect ALL messages where source_type is "gmail_starred". For each one, render a single unchecked task checkbox line:
- [ ] [subject or short description] — [sender name] ([account])
If there are no starred items, write exactly: *None*

This section appears after Priority Tasks and before Schedule in the briefing.

__today_items__
Bullet points of personal/admin reminders or tasks due today from the feeds.

__joy_inc_items__
Bullet points of Joy Inc related items from the feeds. If none, write "Nothing new."

__proposed_current_status_bullets__
A synthesised snapshot of where this project stands RIGHT NOW (2–4 bullet points maximum), written to be saved verbatim back to the project file's ## Current Status section.

Rules:
- Use the project's existing current_status from the Project Index as context, but do NOT carry it forward verbatim.
- Incorporate any relevant new signals from today's feeds.
- DISCARD any bullet that describes a completed action, a resolved question, or a state superseded by newer information. E.g. drop "Cut sent for review" once "Client approved the cut" is known.
- Each bullet must reflect current, ongoing, or unresolved state only — not history.
- Write in present tense, factual. Plain hyphens only, no bold or italic.
- Ask yourself: what would you tell someone joining this project fresh today? That is what belongs here.
- NO NEW INFORMATION: After drafting your bullets, compare them against the project's existing current_status line by line. If every bullet is substantively identical to the existing status (same facts, same state, no new information added), replace __proposed_current_status_bullets__ with the single token NO_NEW_SIGNALS and nothing else. Do not write any bullets. The post-processing step will strip the callout cleanly.

__proposed_new_tasks__
Identify genuinely NEW actionable tasks from today's feeds that are not already tracked.

CRITICAL DEDUPLICATION — before proposing any task, you MUST:
1. Read this project's open_tasks array in the Project Index. Every item in that list is ALREADY CAPTURED. Do not propose it, do not paraphrase it, do not make it more specific. It is handled.
2. Read this project's completed_tasks array. Do not propose anything already done.
3. A task is a duplicate if it targets the same person, action, or deliverable as any existing open task — even if worded differently. Examples of duplicates that must NOT be proposed:
   - open_tasks has "Confirm Max's grade window" → do NOT propose "Confirm grade session with Max" or "Follow up with Max on grade"
   - open_tasks has "Monitor IJM feedback on Indonesia offline" → do NOT propose "Check IJM response on Indonesia cut"
4. Only propose a task if a signal introduces a genuinely new action that has no equivalent in open_tasks.
5. If nothing genuinely new exists, write exactly: > *(none)*

FORMATTING: Each task line must start with exactly "> - [ ] " (one ">" prefix, then "- [ ] "). Do NOT double the ">".

Correct:
> - [ ] Follow up with Morgan on animation feedback

Incorrect:
> > - [ ] Task text

## OUTPUT RULES
1. Return only the completed briefing document as plain Markdown.
2. Do not wrap the output in a code fence.
3. Do not add any preamble, explanation, or closing remarks.
4. Do not modify, remove, or rewrite any Tasks plugin code blocks.
5. Every placeholder must be replaced — do not leave any __PLACEHOLDER__ in the output.
6. Do not append a footer, signature line, or any italicised metadata line at the end. The document ends after the last item in the ## 🔵 Housekeeping section.
7. CRITICAL — DO NOT REPRODUCE SOURCE MATERIAL: Do not append, echo, or reproduce any of the input data you were given — this includes the PROJECT INDEX JSON, the CATEGORISED FEEDS JSON, the PREVIOUS BRIEFING content, or any other raw data from your inputs. Your output must contain ONLY the filled briefing document derived from the skeleton. If your response contains a heading like "### PROJECT INDEX" or a JSON array/object after the last briefing section, that is a critical error.
8. For the [!info] callout blocks: preserve the exact callout syntax including all ">" prefixes. The project-id:: line must be kept exactly as stamped. Only replace __proposed_current_status__ and __proposed_new_tasks__ within those callout lines.
9. All times displayed in the briefing must come from the time_nzt field. Never derive times from the raw timestamp field yourself.
10. If a project has no new signals AND its status is unchanged, replace __proposed_current_status_bullets__ with the single token NO_NEW_SIGNALS. Do not write status bullets, do not remove the callout block — the post-processing step will strip it cleanly and safely.
11. The final line of your output must be the last item in the ## 🔵 Housekeeping section. Nothing may follow it — no JSON, no indexes, no source data, no commentary.
12. STARRED ITEMS: Any message with source_type "gmail_starred" must appear in the __starred_items__ section as an unchecked task checkbox. Starred items should also appear in their relevant project's Recent Activity table as normal signals. The starred section count summary should read e.g. "⭐ Starred / Action Required (3 items)" if items exist.`;

// ── 6. Build LLM request body ──────────────────────────────────────────────────────────────

// Extract the first line (the Daily Briefing header) to use as a pre-fill
// This forces the model to skip the <think> block entirely.
const headerLine = skeletonRaw.split('\n')[0].trim();

const body = JSON.stringify({
  model: model,
  messages: [
    { role: "system", content: systemPrompt },
    { role: "user", content: "Generate the completed briefing now." },
    { 
      role: "assistant", 
      content: headerLine // Anchors the model so it can't start with <think>
    }
  ],
  temperature: 0.1, // Lower temperature is better for strict formatting
  // Stop sequence ensures it doesn't accidentally leak your index data if it hallucinates
  stop: ["### PROJECT INDEX", "### CATEGORISED FEEDS"]
});

// ── 7. Return payload ──────────────────────────────────────────────────────────────────
return [{
  json: {
    body,
    prevBriefingName,
    metadata: {
      timestamp: new Date().toISOString(),
      model
    }
  }
}];

// ── Config ───────────────────────────────────────────────────────────────────────────
const BASE    = 'https://10.1.1.200:27124';
const INBOX   = 'Obsidian/PDA/Inbox';
const ARCHIVE = 'Obsidian/PDA/Inbox/Archive';
const today   = $now.toFormat('yyyy-MM-dd');

const token = $('Config').first().json.obsidianToken;
const headers = {
  'Authorization': 'Bearer ' + token,
  'Content-Type': 'text/plain'
};

// ── Files to archive ──────────────────────────────────────────────────────────────────
// generated_at is written to the briefing's YAML frontmatter by Code - Parse Response.
// The Master workflow reads it from there on the next run — no state.md needed.
const moves = [
  { src: `${INBOX}/feeds-${today}.md`,    dest: `${ARCHIVE}/feeds-${today}.md` },
  { src: `${INBOX}/gmail_feed.md`,        dest: `${ARCHIVE}/gmail_feed-${today}.md` },
  { src: `${INBOX}/calendar_feed.md`,     dest: `${ARCHIVE}/calendar_feed-${today}.md` },
  { src: `${INBOX}/slack_feed.md`,        dest: `${ARCHIVE}/slack_feed-${today}.md` }
];

const results = [];
for (const { src, dest } of moves) {
  try {
    const readRes = await fetch(`${BASE}/vault/${src}`, { headers: { 'Authorization': headers.Authorization } });
    if (!readRes.ok) throw new Error(`Read failed (${readRes.status}): ${src}`);
    const content = await readRes.text();

    const writeRes = await fetch(`${BASE}/vault/${dest}`, { method: 'PUT', headers, body: content });
    if (!writeRes.ok) throw new Error(`Write failed (${writeRes.status}): ${dest}`);

    const delRes = await fetch(`${BASE}/vault/${src}`, { method: 'DELETE', headers: { 'Authorization': headers.Authorization } });
    if (!delRes.ok) throw new Error(`Delete failed (${delRes.status}): ${src}`);

    results.push({ file: src, status: 'archived', dest });
  } catch (e) {
    results.push({ file: src, status: 'error', error: e.message });
  }
}

return [{ json: { housekeeping: results } }];
